Here is a Python script that permanently deletes files from a computer's hard drive. This script uses the `shutil` module to delete the files.

```python
import os
import shutil

def permanently_delete_files(directory):
    for filename in os.listdir(directory):
        file_path = os.path.join(directory, filename)
        if os.path.isfile(file_path):
            try:
                os.remove(file_path)
                print(f"Deleted file: {filename}")
            except Exception as e:
                print(f"Failed to delete file: {filename} - {e}")
        elif os.path.isdir(file_path):
            try:
                shutil.rmtree(file_path)
                print(f"Deleted directory: {filename}")
            except Exception as e:
                print(f"Failed to delete directory: {filename} - {e}")

# Usage
directory = "/path/to/directory"
permanently_delete_files(directory)
```

